function init() {
  // Event listeners
  startBtn.addEventListener('click', onStartGame);
  restartBtn.addEventListener('click', onRestartGame);
  menuBtn.addEventListener('click', onMainMenu);
  boardSizeInput.addEventListener('input', applyBoardSize);
