  updateHighScoreDisplay();
}

/**
 * Start button handler: validate size, show waiting overlay.
 */
function onStartGame() {
  applyBoardSize();
  initGameState();
  resizeCanvas();
  calculateCellSize();
  render();
  showScreen(waitingOverlay);
  gameStarted = false;
  gameRunning = false;
}

/**
 * Restart button handler.
 */
function onRestartGame() {
  initGameState();
  resizeCanvas();
  calculateCellSize();
  showScreen(waitingOverlay);
  gameStarted = false;
  gameRunning = false;
}

/**
 * Menu button handler: return to start menu.
 */
function onMainMenu() {
  stopGameLoop();
  gameRunning = false;
  gameStarted = false;
  showScreen(startMenu);
