npx -y chrome-devtools-axi eval "() => {
  // Comprehensive test
  const tests = [];

  // Test 1: Board size validation
  boardSizeInput.value = 5;
  applyBoardSize();
  tests.push({ name: 'Board size min clamp', pass: boardSize === 10, detail: `got ${boardSize}` });

  boardSizeInput.value = 50;
  applyBoardSize();
  tests.push({ name: 'Board size max clamp', pass: boardSize <= 30, detail: `got ${boardSize}` });

  boardSizeInput.value = 20;
  applyBoardSize();

  // Test 2: Game initialization
  initGameState();
  tests.push({ name: 'Snake starts with 3 segments', pass: snake.length === 3 });
  tests.push({ name: 'Snake in center', pass: snake[0].x >= 5 && snake[0].x <= 15 && snake[0].y >= 5 && snake[0].y <= 15 });
  tests.push({ name: 'Food placed', pass: food !== null });
  tests.push({ name: 'Score starts at 0', pass: score === 0 });

  // Test 3: Movement
  const headBefore = { ...snake[0] };
  moveSnake();
  tests.push({ name: 'Snake moves', pass: snake[0].x !== headBefore.x || snake[0].y !== headBefore.y });
  tests.push({ name: 'Length maintained', pass: snake.length === 3 });

  // Test 4: Eating food
  snake = [{ x: 5, y: 5 }, { x: 4, y: 5 }];
  food = { x: 6, y: 5 };
  direction = { x: 1, y: 0 };
  moveSnake();
  handleEatFood();
  tests.push({ name: 'Snake grows on food', pass: snake.length === 3 });
  tests.push({ name: 'Score increases', pass: score === 10 });

  // Test 5: Wall collisions
  snake = [{ x: 19, y: 5 }, { x: 18, y: 5 }];
  direction = { x: 1, y: 0 };
  moveSnake();
  tests.push({ name: 'Wall collision right', pass: checkCollision() });

  snake = [{ x: -1, y: 5 }, { x: 0, y: 5 }];
  tests.push({ name: 'Wall collision left', pass: checkCollision() });

  snake = [{ x: 5, y: -1 }, { x: 5, y: 0 }];
  tests.push({ name: 'Wall collision top', pass: checkCollision() });

  snake = [{ x: 5, y: 20 }, { x: 5, y: 19 }];
  tests.push({ name: 'Wall collision bottom', pass: checkCollision() });

  // Test 6: Self collision
  snake = [{ x: 3, y: 3 }, { x: 4, y: 3 }, { x: 4, y: 4 }, { x: 3, y: 4 }];
  direction = { x: 1, y: 0 };
  moveSnake();
  tests.push({ name: 'Self collision', pass: checkCollision() });

  // Test 7: Direction controls
  direction = { x: 1, y: 0 };
  nextDirection = { x: 1, y: 0 };
  handleDirectionInput(new KeyboardEvent('keydown', { key: 'ArrowUp' }));
  tests.push({ name: 'ArrowUp works', pass: nextDirection.y === -1 });

  direction = { x: 1, y: 0 };
  nextDirection = { x: 1, y: 0 };
  handleDirectionInput(new KeyboardEvent('keydown', { key: 'ArrowLeft' }));
  tests.push({ name: 'Reverse blocked', pass: nextDirection.x === 1 });

  direction = { x: 0, y: 0 };
  nextDirection = { x: 0, y: 0 };
  handleDirectionInput(new KeyboardEvent('keydown', { key: 'w' }));
  tests.push({ name: 'WASD W works', pass: nextDirection.y === -1 });

  handleDirectionInput(new KeyboardEvent('keydown', { key: 's' }));
  tests.push({ name: 'WASD S works', pass: nextDirection.y === 1 });

  handleDirectionInput(new KeyboardEvent('keydown', { key: 'a' }));
  tests.push({ name: 'WASD A works', pass: nextDirection.x === -1 });

  handleDirectionInput(new KeyboardEvent('keydown', { key: 'd' }));
  tests.push({ name: 'WASD D works', pass: nextDirection.x === 1 });

  // Test 8: High score
  sessionHighScore = 50;
  score = 60;
  tests.push({ name: 'High score updates', pass: updateHighScore() && sessionHighScore === 60 });

  sessionHighScore = 100;
  score = 50;
  tests.push({ name: 'High score unchanged', pass: !updateHighScore() && sessionHighScore === 100 });

  // Summary
  const passed = tests.filter(t => t.pass).length;
  const failed = tests.filter(t => !t.pass).length;
  const summary = `${passed}/${tests.length} tests passed`;
  if (failed > 0) {
    const fails = tests.filter(t => !t.pass).map(t => `${t.name}: ${t.detail}`).join(', ');
    console.log('TESTS FAILED:', fails);
  } else {
    console.log('ALL TESTS PASSED:', summary);
  }
  return summary;
}" 2>&1

